              })}
              <button class="submit-button" type="submit">Send request</button>
            </form>
          </section>
        `;
      }

      function SupportPage() {
        return `
          <main class="page-shell" id="main-content">
            <div class="support-layout">
              <section aria-labelledby="page-title">
                <p class="eyebrow">Support</p>
                <h1 id="page-title">How can we help?</h1>
                <p class="intro">
                  Reach our product support team for account, billing, or technical questions.
                  Share your contact details and we will route your request to the right specialist.
                </p>
              </section>
              ${ContactForm()}
            </div>
